package com.ilia.gikashvili.archmain.ai;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.core.type.TypeReference;
import com.ilia.gikashvili.archmain.security.*; import com.ilia.gikashvili.archmain.common.exception.*;
import com.ilia.gikashvili.archmain.access.service.ProjectAccessService; import com.ilia.gikashvili.archmain.access.policy.Permission;
import com.ilia.gikashvili.archmain.architecture.service.*;
import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class AiController {
 private final AiProviderKeyRepository keys; private final AiAgentRunRepository runs;private final AiKeyCipher cipher;private final AiProviderClient provider;private final ObjectMapper json;private final ProjectAccessService access;private final ArchitectureService architecture;private final ArchitectureOperationsService ops;
 public AiController(AiProviderKeyRepository k,AiAgentRunRepository r,AiKeyCipher c,AiProviderClient p,ObjectMapper j,ProjectAccessService a,ArchitectureService ar,ArchitectureOperationsService o){keys=k;runs=r;cipher=c;provider=p;json=j;access=a;architecture=ar;ops=o;}
 public record CreateKey(@NotNull AiProviderKey.Provider provider,@NotBlank @Size(max=200) String label,@Size(max=4096) String apiKey,@Size(max=200) String model,@Size(max=500) String baseUrl){}
 public record RunRequest(@NotNull UUID keyId,@NotBlank @Size(max=20000) String prompt){}
 private AiProviderKey key(UUID id,UUID user){return keys.findByIdAndUserId(id,user).orElseThrow(()->new NotFoundException("AI key",id));}
 @GetMapping("/users/me/ai-keys") public Object keys(@CurrentUser AuthenticatedUser u){return keys.findByUserIdOrderByCreatedAtDesc(u.id());}
 @PostMapping("/users/me/ai-keys") @ResponseStatus(HttpStatus.CREATED) public Object create(@CurrentUser AuthenticatedUser u,@Valid @RequestBody CreateKey r){AiProviderKey k=new AiProviderKey();k.userId=u.id();k.provider=r.provider();k.label=r.label().trim();String raw=r.apiKey()==null?"":r.apiKey().trim();if(r.provider()==AiProviderKey.Provider.OLLAMA){if(raw.isEmpty())raw="ollama-local";String bu=r.baseUrl()==null||r.baseUrl().isBlank()?AiProviderClient.OLLAMA_DEFAULT:r.baseUrl().trim();if(!bu.matches("(?i)https?://.+"))throw new ValidationException("Ollama base URL must start with http:// or https://");k.baseUrl=bu.replaceAll("/+$","").replaceAll("/api/chat$","");}else if(raw.length()<4)throw new ValidationException("API key must contain at least four characters");k.encryptedKey=cipher.encrypt(raw);k.last4=r.provider()==AiProviderKey.Provider.OLLAMA&&raw.equals("ollama-local")?"local":raw.substring(raw.length()-4);k.model=r.model()==null||r.model().isBlank()?switch(r.provider()){case OPENAI->"gpt-4o-mini";case ANTHROPIC->"claude-haiku-4-5";case GEMINI->"gemini-2.5-flash";case OPENROUTER->"openai/gpt-4o-mini";case OLLAMA->"qwen3:4b";}:r.model();return keys.save(k);}
 @GetMapping("/users/me/ai-keys/ollama/models") public Object ollamaModels(@CurrentUser AuthenticatedUser u,@RequestParam(required=false) String baseUrl){try{return Map.of("ok",true,"models",provider.ollamaModels(baseUrl));}catch(Exception e){return Map.of("ok",false,"models",List.of(),"message",safe(e));}}
 @DeleteMapping("/users/me/ai-keys/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id,@CurrentUser AuthenticatedUser u){keys.delete(key(id,u.id()));}
 @PostMapping("/users/me/ai-keys/{id}/test") public Object test(@PathVariable UUID id,@CurrentUser AuthenticatedUser u){var k=key(id,u.id());try{provider.call(k,"Reply briefly.","Say OK",true);return Map.of("ok",true,"message",k.provider==AiProviderKey.Provider.OLLAMA?"Ollama answered with "+k.model:"Provider connection successful");}catch(Exception e){return Map.of("ok",false,"message",safe(e));}}
 private String safe(Exception e){if(e instanceof IllegalStateException||e instanceof ValidationException)return e.getMessage();if(e instanceof java.net.http.HttpTimeoutException)return "Provider request timed out";return "Provider request failed or returned invalid JSON/operations";}
 private Map<String,Object> response(AiAgentRun r){Map<String,Object> m=json.convertValue(r,new TypeReference<>(){});try{m.put("operations",json.readTree(r.operationsJson));}catch(Exception e){m.put("operations",List.of());}return m;}
 @GetMapping("/projects/{projectId}/ai/agent-runs") public Object list(@PathVariable UUID projectId,@CurrentUser AuthenticatedUser u){access.require(projectId,u.id(),Permission.READ);return runs.findTop50ByProjectIdOrderByCreatedAtDesc(projectId).stream().map(this::response).toList();}
 @PostMapping("/projects/{projectId}/ai/agent-runs") public Object run(@PathVariable UUID projectId,@CurrentUser AuthenticatedUser u,@Valid @RequestBody RunRequest request){access.require(projectId,u.id(),Permission.EDIT);var k=key(request.keyId(),u.id());AiAgentRun r=new AiAgentRun();r.projectId=projectId;r.userId=u.id();r.keyId=k.id;r.prompt=request.prompt();r.status="RUNNING";runs.saveAndFlush(r);
 try{String system="You edit architecture diagrams. Return ONLY JSON {\"summary\":string,\"operations\":[...]}. Exact operation forms: {op:node.add,node:{id,type,label,description,x,y,properties:{}}}, {op:node.update,id,patch:{label,type,description,x,y,properties}}, {op:node.remove,id}, {op:edge.add,edge:{id,type,sourceId,targetId,label,properties:{}}}, {op:edge.update,id,patch:{type,label,sourceId,targetId,properties}}, {op:edge.remove,id}. All op values are strings, all ids unique strings. Edges must reference existing nodes. Node types include service,database,cache,queue,client. Do not delete existing items unless requested. Use at most 500 operations.";
 String text=provider.call(k,system,"Current architecture: "+json.writeValueAsString(architecture.getDocument(projectId,u.id()))+"\nRequest: "+request.prompt(),false).trim();if(text.startsWith("```")){text=text.substring(text.indexOf('\n')+1);text=text.substring(0,text.lastIndexOf("```"));}JsonNode result=json.readTree(text);if(!result.path("operations").isArray()||!result.path("summary").isTextual())throw new IllegalStateException("Provider must return summary and operations array");List<Map<String,Object>> operations=json.convertValue(result.get("operations"),new TypeReference<>(){});r.summary=result.get("summary").asText();r.operationsJson=json.writeValueAsString(operations);if(!operations.isEmpty())synchronized(ops.lockFor(projectId)){ops.apply(projectId,u.id(),"ai-run:"+r.id,operations);}r.status="SUCCEEDED";
 }catch(Exception e){r.status="FAILED";r.error=safe(e);}return response(runs.saveAndFlush(r));}
}
